      "htmlContent": "<ul class=\"checklist-items\">\n<li class=\"checklist-item\"><label class=\"checklist-label\"><input type=\"checkbox\"  class=\"task-checkbox\" data-text=\"Organisation des équipes (schéma + justification du type de chaque équipe)\"> <span class=\"chk-text\">Organisation des équipes (schéma + justification du type de chaque équipe)</span></label></li>\n<li class=\"checklist-item\"><label class=\"checklist-label\"><input type=\"checkbox\"  class=\"task-checkbox\" data-text=\"Choix argumenté d'un cadre d'agilité à l'échelle\"> <span class=\"chk-text\">Choix argumenté d'un cadre d'agilité à l'échelle</span></label></li>\n<li class=\"checklist-item\"><label class=\"checklist-label\"><input type=\"checkbox\"  class=\"task-checkbox\" data-text=\"Roadmap mise à jour intégrant les correctifs\"> <span class=\"chk-text\">Roadmap mise à jour intégrant les correctifs</span></label></li>\n<li class=\"checklist-item\"><label class=\"checklist-label\"><input type=\"checkbox\"  class=\"task-checkbox\" data-text=\"Grille de priorisation des bugs et backlog de bugs ordonné\"> <span class=\"chk-text\">Grille de priorisation des bugs et backlog de bugs ordonné</span></label></li>\n<li class=\"checklist-item\"><label class=\"checklist-label\"><input type=\"checkbox\"  class=\"task-checkbox\" data-text=\"Tableau des dépendances et registre des risques\"> <span class=\"chk-text\">Tableau des dépendances et registre des risques</span></label></li>\n<li class=\"checklist-item\"><label class=\"checklist-label\"><input type=\"checkbox\"  class=\"task-checkbox\" data-text=\"Support de Sprint Review multi-équipes\"> <span class=\"chk-text\">Support de Sprint Review multi-équipes</span></label></li>\n</ul>",
