      "htmlContent": "<ul class=\"checklist-items\">\n<li class=\"checklist-item\"><label class=\"checklist-label\"><input type=\"checkbox\"  class=\"task-checkbox\" data-text=\"Plan d'étude, guide d'entretien et synthèse de recherche (3 insights, 1 persona, 2 JTBD)\"> <span class=\"chk-text\">Plan d'étude, guide d'entretien et synthèse de recherche (3 insights, 1 persona, 2 JTBD)</span></label></li>\n<li class=\"checklist-item\"><label class=\"checklist-label\"><input type=\"checkbox\"  class=\"task-checkbox\" data-text=\"Cartographie des parties prenantes et plan de communication\"> <span class=\"chk-text\">Cartographie des parties prenantes et plan de communication</span></label></li>\n<li class=\"checklist-item\"><label class=\"checklist-label\"><input type=\"checkbox\"  class=\"task-checkbox\" data-text=\"Compte rendu d'atelier d'alignement avec les arbitrages\"> <span class=\"chk-text\">Compte rendu d'atelier d'alignement avec les arbitrages</span></label></li>\n<li class=\"checklist-item\"><label class=\"checklist-label\"><input type=\"checkbox\"  class=\"task-checkbox\" data-text=\"Vision, OKR et roadmap mis à jour\"> <span class=\"chk-text\">Vision, OKR et roadmap mis à jour</span></label></li>\n<li class=\"checklist-item\"><label class=\"checklist-label\"><input type=\"checkbox\"  class=\"task-checkbox\" data-text=\"Outil de recalcul du plan de release\"> <span class=\"chk-text\">Outil de recalcul du plan de release</span></label></li>\n<li class=\"checklist-item\"><label class=\"checklist-label\"><input type=\"checkbox\"  class=\"task-checkbox\" data-text=\"Rapport mensuel d'une page (quantitatif et qualitatif)\"> <span class=\"chk-text\">Rapport mensuel d'une page (quantitatif et qualitatif)</span></label></li>\n</ul>",
